					// We append a search + limit to the filter. 
					var searchPart = " +[search:" + fieldMode + "[" + cleanPat + "]limit[" + (this._maxMatch + 5) + "]]";

					allOptions = this._widget.wiki.filterTiddlers(baseFilter + searchPart);
					// ============================================
