	 */
	var insertInto = function (node, text, posBefore, posAfter, template, tiddlerTitle) {
		//DEBUG console.log( "__INSERT : "+template.pattern+":"+template.filter+":"+template.mask+":"+template.field+":"+template.start+":"+template.end );
		var val = node.value;
		var sStart = template.start !== undefined ? template.start : '[[';
		var sEnd = template.end !== undefined ? template.end : ']]';

		var newVal;
		// Check if the closing characters already exist immediately after the cursor
		if (sEnd && val.substring(posAfter, posAfter + sEnd.length) === sEnd) {
			newVal = val.slice(0, posBefore) + sStart + text + val.slice(posAfter);
		} else {
			newVal = val.slice(0, posBefore) + sStart + text + sEnd + val.slice(posAfter);
		}

		//console.log("__INSERT s="+sStart+" e="+sEnd);
		//console.log ("__INSERT pb="+posBefore+" pa="+posAfter+" txt="+text);
		//console.log( "NEW VAL = "+newVal );
		// WARN : Directly modifie domNode.value.
		// Not sure it does not short-circuit other update methods of the domNode....
		// i.e. could use widget.updateEditor(newVal) from edit-comptext widget.
		//      but how to be sure that cursor is well positionned ?
		node.value = newVal;

		// Determine offset: check caret-pos field first, then template.startOffset
		var offset = undefined;
		if (tiddlerTitle) {
			var tiddler = $tw.wiki.getTiddler(tiddlerTitle);
			if (tiddler && tiddler.fields["caret-pos"]) {
				var valField = parseInt(tiddler.fields["caret-pos"], 10);
				if (!isNaN(valField)) {
					offset = valField;
				}
			}
		}

		if (offset === undefined && template.startOffset !== undefined) {
			offset = template.startOffset;
		}

		if (offset !== undefined) {
			let cursorPos = posBefore + offset;
			node.setSelectionRange(cursorPos, cursorPos);
		}
		else {
			node.setSelectionRange(posBefore + text.length + sStart.length + sEnd.length, posBefore + text.length + sStart.length + sEnd.length);
		}
	};
	/**
	 * Add an '\' in front of -\^$*+?.()|[]{}
	 */
	var regExpEscape = function (s) {
		return s.replace(/[-\\^$*+?.()|[\]{}]/g, "\\$&");
	};
	/**
	 * Add an element in the DOM.
	 */
	var create = function (tag, o) {
		var element = document.createElement(tag);

		for (var i in o) {
			var val = o[i];

			if (i === "inside") {
				$(val).appendChild(element);
			}
			else if (i === "around") {
				var ref = $(val);
				ref.parentNode.insertBefore(element, ref);
				element.appendChild(ref);
			}
			else if (i in element) {
				element[i] = val;
			}
			else {
				element.setAttribute(i, val);
			}
		}

		return element;
	};


	/**
